const date = $now.setZone('Asia/Dubai').toISODate();
const shouldRefresh = $getWorkflowStaticData('global').calendar?.fetchedOn !== date;
return [{ json: { shouldRefresh, erpBase: 'https://erp.multimax.cloud' } }];

function parseMinute(value) {
  const match = typeof value === 'string' && /^(\d{1,2}):(\d{2}):00(?:\.0+)?$/.exec(value);
  if (!match || Number(match[1]) > 23 || Number(match[2]) > 59) return null;
  return Number(match[1]) * 60 + Number(match[2]);
}
const reply = $input.first().json;
const shifts = ['Morning', 'Afternoon', 'Morning (Fri)', 'Afternoon (Fri)'];
const lookup = new Map(Array.isArray(reply.data) ? reply.data.map(shift => [shift.name, shift]) : []);
const rows = shifts.map(shift => lookup.get(shift));
const holidayList = rows[0]?.holiday_list;
const windows = rows.map(row => [parseMinute(row?.start_time), parseMinute(row?.end_time)]);
const validWindows = windows.every(([open, close]) => open != null && close != null && open < close);
if (!holidayList || rows.some(row => row?.holiday_list !== holidayList) || !validWindows ||
    windows[0][1] > windows[1][0] || windows[2][1] > windows[3][0]) {
  console.warn('Delivery shift refresh failed. Checking the last known calendar.');
  return [{ json: {} }];
}
return [{ json: { holidayList, normal: windows.slice(0, 2), friday: windows.slice(2) } }];

const list = $input.first().json.data;
const shifts = $('Validate dispatch shifts').first().json;
const validDate = value => typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) && DateTime.fromISO(value).isValid;
if (list?.name !== shifts.holidayList || !validDate(list.from_date) || !validDate(list.to_date) ||
    list.from_date > list.to_date || !Array.isArray(list.holidays) ||
    list.holidays.some(row => !validDate(row.holiday_date))) {
  console.warn('Delivery holiday list refresh failed. Checking the last known calendar.');
  return [{ json: {} }];
}
const state = $getWorkflowStaticData('global');
state.calendar = {
  normal: shifts.normal,
  friday: shifts.friday,
  fromDate: list.from_date,
  toDate: list.to_date,
  holidays: [...new Set(list.holidays.map(row => row.holiday_date))],
  fetchedOn: $now.setZone('Asia/Dubai').toISODate(),
};
return [{ json: {} }];

function windowsFor(day, calendar, holidays) {
  if (day.weekday === 7 || holidays.has(day.toISODate())) return [];
  return day.weekday === 5 ? calendar.friday : calendar.normal;
}
const now = $now.setZone('Asia/Dubai');
const date = now.toISODate();
const calendar = $getWorkflowStaticData('global').calendar;
if (!calendar || date < calendar.fromDate || date > calendar.toDate) {
  throw new Error('Dispatch calendar coverage is missing or expired');
}
const minute = now.hour * 60 + now.minute;
const windows = windowsFor(now, calendar, new Set(calendar.holidays));
if (!windows.some(([open, close]) => minute >= open && minute < close)) return [];
return [{ json: { evaluatedAt: now.toISO() } }];

const pages = $input.all().map(item => item.json.data);
if (!pages.length || pages.some(page => !Array.isArray(page)) || pages.at(-1).length >= 100) {
  throw new Error('Active POS scan did not return a complete set of pages');
}
const active = pages.flat();
const names = new Set();
for (const row of active) {
  if (!row.name || !['To Deliver', 'Out for Delivery'].includes(row.status) || names.has(row.name)) {
    throw new Error('Active POS scan returned an unexpected row');
  }
  names.add(row.name);
}
const state = $getWorkflowStaticData('global');
if (!active.length && Object.keys(state.sent ?? {}).length) state.sent = {};
return active.map(json => ({ json }));

function statusVersions(reply) {
  if (!Array.isArray(reply.docinfo?.versions)) throw new Error('ERP returned no POS Version list');
  const result = [];
  for (const version of reply.docinfo.versions) {
    let data;
    try {
      data = typeof version.data === 'string' ? JSON.parse(version.data) : version.data;
    } catch {
      throw new Error('ERP returned an invalid POS Version');
    }
    const change = data?.changed?.find(row => row[0] === 'status' && row[1] !== row[2]);
    if (change) result.push({ name: version.name, creation: version.creation, from: change[1], to: change[2], audit: data.updater_reference?.pos_delivery });
  }
  return result;
}
function erpTime(value) {
  return DateTime.fromISO(value.replace(' ', 'T'), { zone: 'Asia/Dubai' }).setZone('Asia/Dubai');
}
function windowsFor(day, calendar, holidays) {
  if (day.weekday === 7 || holidays.has(day.toISODate())) return [];
  return day.weekday === 5 ? calendar.friday : calendar.normal;
}
function workingMilliseconds(start, now, calendar, holidays) {
  let elapsed = 0;
  for (let day = start.startOf('day'); day <= now; day = day.plus({ days: 1 })) {
    for (const [open, close] of windowsFor(day, calendar, holidays)) {
      const lower = Math.max(start.toMillis(), day.plus({ minutes: open }).toMillis());
      const upper = Math.min(now.toMillis(), day.plus({ minutes: close }).toMillis());
      elapsed += Math.max(0, upper - lower);
    }
  }
  return elapsed;
}

const state = $getWorkflowStaticData('global');
const calendar = state.calendar;
const holidays = new Set(calendar.holidays);
const now = erpTime($('Check working window').first().json.evaluatedAt);
const observed = new Map();
const candidates = [];
const sent = { ...state.sent };
const before = Object.keys(sent).length;
for (const [index, item] of $input.all().entries()) {
  const pos = $('Unpack active POS').itemMatching(index).json;
  observed.set(pos.name, null);
  const entry = statusVersions(item.json)[0];
  if (!entry || !entry.audit || !entry.name || !entry.creation) {
    console.warn(`Overdue review needed for ${pos.name}: no audited stage-entry Version`);
    continue;
  }
  if (entry.to !== pos.status) continue; // Changed while scanning. Try next tick.
  if (pos.status === 'Out for Delivery' && (entry.audit.action !== 'Out for Delivery' || !entry.audit.driver)) {
    console.warn(`Overdue review needed for ${pos.name}: dispatch Version has no driver`);
    continue;
  }
  const key = JSON.stringify([pos.name, pos.status, entry.name]);
  observed.set(pos.name, key);
  if (sent[key]) continue;
  const start = erpTime(entry.creation);
  if (!start.isValid || start > now || start.toISODate() < calendar.fromDate) {
    console.warn(`Overdue review needed for ${pos.name}: stage entry falls outside calendar coverage`);
    continue;
  }
  const elapsed = workingMilliseconds(start, now, calendar, holidays);
  const hours = pos.status === 'To Deliver' ? 4 : 8;
  if (elapsed >= hours * 3600000) {
    candidates.push({ json: { pos, key, entry: entry.name, elapsed, hours, evaluatedAt: now.toISO() }, pairedItem: { item: index } });
  }
}
for (const key of Object.keys(sent)) {
  const [name] = JSON.parse(key);
  const current = observed.get(name);
  // Keep keys for rows whose current stage could not be confirmed.
  if (!observed.has(name) || (current && current !== key)) delete sent[key];
}
if (Object.keys(sent).length !== before) state.sent = sent;
return candidates;

function statusVersions(reply) {
