}
function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'})[c]);
}
function lines(title, pos, dn, audit) {
  const row = (label, value) => value ? `${label}: ${escapeHtml(value)}` : null;
  const url = `https://erp.multimax.cloud/app/pos-upload/${encodeURIComponent(pos.name)}`;
  return [
    `<b>${escapeHtml(title)}</b>`,
    `POS Upload: <a href="${escapeHtml(url)}">${escapeHtml(pos.name)}</a>`,
    row('Customer', pos.customer),
    row('Delivery Note', dn),
    row('Driver', audit?.driver_name || audit?.driver),
    row('Recorded by', audit?.recorded_by_name || audit?.recorded_by),
  ].filter(Boolean);
}
function erpTime(value) {
  return DateTime.fromISO(value.replace(' ', 'T'), { zone: 'Asia/Dubai' }).setZone('Asia/Dubai');
}
function messageTime(timestamp) {
  return timestamp.setLocale('en-GB').toFormat('dd MMM yyyy, HH:mm');
}
function currentDeliveryNote(reply) {
  if (!Array.isArray(reply.data)) throw new Error('ERP returned no Delivery Note list');
  return reply.data.length === 1 ? reply.data[0].name : null;
}

const alerts = [];
for (const [index, item] of $input.all().entries()) {
  const candidate = $('Find overdue entries').itemMatching(index).json;
  const current = $('Re-read POS').itemMatching(index).json.data;
  const entry = statusVersions(item.json)[0];
  if (current?.name !== candidate.pos.name || current.status !== candidate.pos.status ||
      entry?.name !== candidate.entry || entry.to !== current.status) continue;
  const dn = currentDeliveryNote($('Find current DN').itemMatching(index).json);
  const dispatchStage = current.status === 'To Deliver';
  const audit = !dispatchStage || entry.audit?.action === 'Delivery Return' ? entry.audit : null;
  const linesOfAlert = lines(dispatchStage ? 'Overdue for dispatch' : 'Overdue for delivery', current, dn, audit);
  const minutes = Math.floor(candidate.elapsed / 60000);
  linesOfAlert.push(
    `Time: ${messageTime(erpTime(candidate.evaluatedAt))}`,
    `Stage: ${current.status}`,
    `Time in stage: ${Math.floor(minutes / 60)} h ${minutes % 60} min`,
    `Threshold: ${candidate.hours} working hours`,
  );
  alerts.push({ json: { text: linesOfAlert.join('\n'), key: candidate.key }, pairedItem: { item: index } });
}
return alerts;

const input = $input.all();
const state = $getWorkflowStaticData('global');
const sent = { ...state.sent };
for (let index = 0; index < input.length; index++) {
  const { key } = $('Build current-stage alert').itemMatching(index).json;
  sent[key] = Date.now();
}
state.sent = sent;
return [{ json: { sent: input.length } }];
